"""Original, offline-aware first-use setup for the persistent personal practicum.

Public API:
  TECHNOLOGY_STARTS[mission_id] -> complete HTML section, no side effects.
  technology_start(mission_id) -> the same section; unknown IDs fail loudly.
  STAGE_TECHNOLOGIES[mission_id] -> introduced/continues tuples.
  PASSPORT_FIELDS -> common minimum fields for a reader-owned passport.

This is teaching content, not an installer or an assertion of prepared runtimes.
The root builder inserts sections before mission analysis. No passwords, current
machine paths, downloaded archives, actual checksums or real runtime state here.
"""

PASSPORT_FIELDS = (
    'Официальный источник и дата получения',
    'Точная версия, редакция, ОС и архитектура',
    'Ожидаемый SHA-256/подпись и источник доверия к ним',
    'Фактический SHA-256 полученного файла или digest образа',
    'Пути программы, данных и действующей конфигурации',
    'Пользователь, команда запуска/остановки, адреса и доступ',
    'Журналы, резервная копия и способ восстановления',
    'Положительная/отрицательная проверки, дата и найденные ограничения',
)


def _block(title, body):
    return '<section class="technology-start" data-technology-start><h2>' + title + '</h2>' + body.strip() + '</section>'


TECHNOLOGY_STARTS = {
    'P00-rescue-bootstrap': _block('Первый комплект: самостоятельно получить и установить основание', r'''
<p>Эта стадия создаёт один продолжающийся личный мир. Сначала нужны QEMU, средство запуска Python и установочный образ Linux; PostgreSQL, Jenkins и остальные технологии здесь ещё не устанавливаются. Они появятся перед собственными заявками. Готового скачанного гостя в книге нет: создание пустого qcow2 не устанавливает ОС.</p>
<ol><li>Дома с интернетом самостоятельно открой <a href="https://www.qemu.org/download/">официальную страницу QEMU</a>, выбери поддерживаемую поставку для домашнего Ubuntu и разрешённого рабочего Windows. Запиши источник, версию и архитектуру. Windows-комплект включает нужные DLL и firmware, а не один exe. Указанная сайтом сторонняя сборка проверяется по её опубликованному происхождению и составу; книга не содержит готового переносимого комплекта.</li>
<li>На <a href="https://releases.ubuntu.com/24.04/">официальной странице Ubuntu 24.04</a> найди Server amd64, SHA256SUMS и подпись. По <a href="https://ubuntu.com/tutorials/how-to-verify-ubuntu">руководству проверки Ubuntu</a> сначала подтверди подпись списка доверенным ключом, затем совпадение суммы ISO. Хеш, скачанный вместе с подменённым файлом с неизвестного сайта, не устанавливает подлинность.</li>
<li>Проверь Python 3.10+; для разрешённого Windows без системной установки есть <a href="https://docs.python.org/3/using/windows.html#the-embeddable-package">официальная embeddable-поставка</a>. Сохрани её целиком. На Ubuntu используй пакет своей ОС. Отдельно зафиксируй контрольные суммы загруженного комплекта для проверки после копирования.</li>
<li>Прочитай <a href="../labs-personal/vm/README.txt">инструкцию личной VM</a>, выполни doctor, выбери профиль и создай новый диск только при первом создании мира. Проверь поддержку machine type и CPU обеими сборками QEMU. Подключи проверенный ISO и установи ОС через консоль на диск гостя. Не выбирай диск физического компьютера и не подключай его каталоги для удобства. Минимальный первый профиль — учебная оценка, а не измеренная гарантия расхода.</li>
<li>Настрой имя машины, обычного пользователя, пароль, часовой пояс и консоль. Дойди до загрузки с установленного диска без ISO. Сохрани /etc/os-release, uname -m, lsblk, выбранный профиль QEMU и способ штатного выключения. На этом этапе достаточно консоли: OpenSSH вводится в P01. Не выполняй весь guest/bootstrap.sh ради старта: он перечисляет инструменты будущих этапов.</li></ol>
<p>Паспорт основания храни рядом с личным runtime, не в публичном репозитории. Для каждой новой технологии добавляй отдельный файл: официальный URL и дату; точную версию/архитектуру; ожидаемую и фактическую сумму и способ доверия к первой; пути программы/config/data; пользователя и запуск/остановку; адреса и вход; журналы; резерв/восстановление; контрольные проверки. Секреты в паспорт не вписывают: только место и способ их защищённого получения.</p>
<p>Перед переносом выполни poweroff внутри гостя и дождись выхода QEMU. Переноси закрытый самостоятельный диск с manifest; после копирования проверь суммы. Запусти этот же мир на другом разрешённом компьютере и найди сохранённый контрольный файл. Одновременно две writable-копии не развиваются. На рабочем ПК запуск может регистрироваться системой; абсолютного отсутствия следов книга не обещает. Если исполнение запрещено, локальная VM не является доступным режимом.</p>
'''),
    'P01-management-ssh': _block('Первая установка OpenSSH и собственная настройка входа', r'''
<p>Продолжай установленного Linux-гостя P00 через консоль. Сервер OpenSSH добавляется сейчас, а не подразумевается готовым. Дома найди <a href="https://ubuntu.com/server/docs/how-to/security/openssh-server/">официальную инструкцию Ubuntu</a> и сверь названия openssh-server и openssh-client с каталогом пакетов своей версии ОС.</p>
<p>Для автономной установки пакетов используем один договор. В том же сохраняемом госте обнови подписанные индексы APT, посмотри apt-cache policy нужного пакета, выбери точную версию и через apt-get --download-only подготовь его и требуемые изменения зависимостей. Сохрани deb-файлы и проверенные метаданные в личный комплект стадии. Другая ОС или другая архитектура не являются равной средой. Проверь полноту комплекта заранее: на работе установка с --no-download должна обходиться без обращения к сети и завершаться ошибкой при отсутствии зависимости. Подпись APT относится к цепочке метаданных и хешей пакетов, а не к произвольному deb с форума.</p>
<p>После установки в госте выясни способ активации ssh.service/ssh.socket, расположение sshd_config и включаемых файлов; посмотри systemctl status ssh и ss -ltnp. Сначала создай своего пользователя, каталог .ssh и authorized_keys с подходящим владельцем и правами. Ключ клиента создаётся и хранится в личном комплекте; закрытая часть на сервер не копируется. Сверь fingerprint серверного ключа через консоль до первого доверенного подключения.</p>
<p>Проверь sshd -t перед применением конфигурации и sshd -T для её итоговых значений с учётом подходящего контекста Match. Сохрани открытый аварийный сеанс, перечитай или перезапусти именно свою службу и новым сеансом проверь вход. Доступ без нужного ключа должен быть отвергнут. После этого можно осознанно ограничивать парольный вход и пользователей; не отключай единственный работающий способ раньше приёмки замены.</p>
<p>В паспорт SSH добавь версию пакета, ключ узла/fingerprint, активный unit, файлы Include, адрес/порт гостя, отдельный loopback-порт QEMU на хосте, разрешённого пользователя, known_hosts, путь журналов journalctl -u ssh. Штатная остановка VM не удаляет ключи и authorized_keys. Следующие главы используют тот же вход; изменение host key сначала расследуют, а не лечат удалением known_hosts. Правила управления пакетами: <a href="https://ubuntu.com/server/docs/how-to/software/package-management/">документация Ubuntu APT</a>.</p>
'''),
    'P02-bastion-access': _block('Продолжить SSH: добавить роль бастиона без потери прежней конфигурации', r'''
<p>OpenSSH уже установлен в P01. Сначала сопоставь сохранённый fingerprint, пользователя и конфигурацию с фактическим состоянием; повторная установка и новый ключ не являются первым действием. Если нужен второй сервер-бастион, это новая роль с собственным диском/адресом и паспортом, а не переинициализация исходного сервера. В карте этот профиль пока не создан.</p>
<p>По <a href="https://www.openssh.com/manual.html">официальным руководствам OpenSSH</a> найди ProxyJump и правила пересылки, затем выбери маршрут «клиент → бастион → целевой сервер». На новой роли установи тот же подходящий пакет из комплекта P01, создай отличимый host key и узкого пользователя. У целевого сервера сохраняются прежние identity, файлы и данные. Запиши обе проверки ключей: доверие к бастиону не заменяет доверия к конечному серверу.</p>
<p>Настрой клиентский Host/HostName/User/IdentityFile и ProxyJump; отдельно реши, какие назначения разрешено открывать с бастиона. Не включай пересылку агентского ключа автоматически: jump-маршрут не требует отдавать закрытый ключ серверу. Сначала докажи вход через бастион, затем по правилам учебной топологии убери прямой маршрут и проверь его отказ. Один удачный ProxyJump при оставленном прямом доступе не выполняет условие.</p>
<p>В паспорт добавляются карта переходов, ограничения forwarding, серверные журналы обеих ролей и аварийный вход. Сохраняются изменения SSH P01; неверная настройка исправляется через консоль с записью причины. Возврат всей VM к исходному снимку здесь не считается штатным выполнением задания.</p>
'''),
    'P03-packet-path': _block('Первые сетевые инструменты: получить пакеты и проверить свой стек', r'''
<p>В той же VM подготовь по протоколу P01 пакеты iproute2, iputils-ping и tcpdump для выбранной Ubuntu. Официальный смысл ip и сетевых пространств имён сверяй с <a href="https://www.kernel.org/doc/html/latest/networking/">документацией ядра</a>, захват — с <a href="https://www.tcpdump.org/manpages/tcpdump.1.html">руководством tcpdump</a>. Запиши версии ip -Version и tcpdump --version, путь бинарников и требуемые полномочия. Наличие команды в HTML-справке не означает её установку в госте.</p>
<p>Сначала перечисли фактические интерфейсы, маршруты, слушатели и namespace. Прочитай netlab.sh до первого запуска: он создаёт три study-* стека только внутри гостя и намеренно выключает пересылку маршрутизатора. Если они уже существуют, продолжай их исследование; не удаляй, чтобы получить удобную исходную картинку. Проверка и ошибка отказа повторного up защищают текущую работу.</p>
<p>Выбери два места захвата и узкий фильтр, предскажи MAC/IP/TTL до команды. Создай каталоги журналов, доступные только учебному пользователю, и сохрани исходные выводы. Успешный ping до шлюза и неуспешный до сервера — допустимая исходная неисправность; устрани её минимальным объяснённым изменением и сохрани фактический конфиг.</p>
<p>Namespace и одноразовые sysctl живут в памяти ядра. Чтобы продолжить после poweroff, запиши собственное итоговое описание интерфейсов/маршрутов/правил и порядок его применения; исходный netlab.sh не содержит будущих исправлений за тебя. Рецепт создания и журнал отклонений сохраняются вместе. Паспорт сети включает адресный план, имена интерфейсов, пути конфигов/pcap, выбранные привилегии и положительный/отрицательный маршрут. Подготовленный скрипт пока не объявлен пройденным в вашей VM.</p>
'''),
    'P04-vlan-routing': _block('Первая установка Packet Tracer и создание своей сохраняемой топологии', r'''
<p>Дома самостоятельно найди Packet Tracer в <a href="https://www.netacad.com/resources/lab-downloads">официальном Cisco Resource Hub</a>, войди своей разрешённой учётной записью и проверь требования выбранного выпуска. Запиши точную версию установщика, ОС, архитектуру, официальный источник и доступные данные целостности. Если отдельный опубликованный хеш не найден, так и запиши; свой SHA-256 помогает проверить перенос, но сам не доказывает происхождение. Установка и принятие условий выполняются владельцем компьютера в разрешённой среде.</p>
<p>На обоих компьютерах нужна совместимая версия. Официальный portable-режим без следов здесь не установлен. При запрете установки на Windows не обещай перенести установленную программу копированием её каталога: остаётся разрешённый удалённый GUI либо другой согласованный режим. Сам файл .pkt на флэшке не включает приложение.</p>
<p>После установки открой Help и найди CLI/Simulation на простейшем новом устройстве. Затем самостоятельно собери <a href="../labs-personal/packet-tracer/README.txt">подготовленную топологию</a>: модели, кабели, номера портов, VLAN и адреса сверяются до загрузки cfg. Вставляй конфигурации только соответствующему устройству, дожидайся интерактивного подтверждения. Здесь ещё нет выданного готового .pkt и нет проверенного прогона этих конфигураций.</p>
<p>Проверь базовые маршруты и ARP, сохрани конфиг устройства через copy running-config startup-config и общий файл через File → Save. Закрой и снова открой тот же .pkt, найди свои названия/исправления и повтори путь пакета. Затем вводи резервную линию и OSPF по заданию. Не создавай каждый раз пустой новый файл: основной путь сохраняется, отдельная контрольная копия нужна до конкретной рискованной операции. Паспорт PT хранит версию, путь .pkt, адреса и соответствие портов, сохранённые конфиги и ограничения модели.</p>
'''),
    'P05-dhcp-dns-tls': _block('Впервые настроить выдачу адресов, имена и свой TLS', r'''
<p>В существующем .pkt продолжаются те же маршрутизаторы и Server: это не новая сеть. DHCP-пул и DNS-запись вводятся после проверки маршрута, а не вместе с его сбросом. До каждой добавки запиши действительные адреса и состояние аренды. Получение адреса не доказывает работу DNS или защищённого имени.</p>
<p>Для настоящего Linux-прохода дома найди <a href="https://thekelleys.org.uk/dnsmasq/doc.html">официальное описание dnsmasq</a> и <a href="https://docs.openssl.org/3.0/man1/openssl-req/">руководство OpenSSL</a>; подготовь подходящие dnsmasq-base, dnsutils, openssl и curl из подписанного репозитория своей Ubuntu. dnsmasq-base выбран как бинарник без обязательного запуска системной службы. Сверь версии и комплект зависимостей, затем установи автономно в того же гостя.</p>
<p>До старта dnsmasq определи namespace, интерфейс, адрес слушателя, DHCP-диапазон и исключения, маршрутизатор, домен, DNS-запись, файл аренд и журнал. Размещай собственные файлы в /srv/study/dns; не заменяй настройки systemd-resolved хоста и не запускай второй DHCP-сервер в чужом сегменте. Проверь dnsmasq --test с собственным conf-file, затем один явно выбранный процесс в учебной сети. Просмотри аренду и DNS-ответ от этого адреса, сравни запрос с правильным и неправильным именем.</p>
<p>Для TLS создай свою учебную CA и серверный ключ в закрытом каталоге /srv/study/tls; впиши фактическое имя сервиса в Subject Alternative Name. Настрой выбранный тестовый HTTPS-процесс с этими файлами. Клиент использует curl --cacert с конкретным CA-файлом внутри гостя; устанавливать корневой CA в рабочий Windows не требуется. Правильное имя должно пройти проверку, неправильное — отвергнуться. Нельзя заменять этот критерий curl -k. Паспорт содержит издателя/имя/срок сертификата и пути ключей, но не их содержимое; lease-файл, DNS-конфиг и CA продолжаются в следующих заданиях. Интегрированный постоянный DNS/TLS-профиль пока требует вашего фактического запуска.</p>
'''),
    'P06-service-socket': _block('Настроить первую службу поверх существующей машины', r'''
<p>Linux, SSH и маршруты остаются прежними. Перед опытом проверь Python в госте; при отсутствии подготовь python3 из официального репозитория Ubuntu по договору P01. Домашний Python для world.py и Python внутри гостя — два разных процесса и два места установки.</p>
<p>Для первого HTTP используй пустой учебный каталог и стандартный модуль http.server; не обслуживай каталог личных документов. Явно выбери адрес и порт, запускающего пользователя и namespace. Подготовь /srv/study/http с контрольным файлом и журналом. Сначала проверь локальный сокет и запрос, затем клиентский путь. Неправильная привязка к loopback должна объяснимо отличаться от закрытого маршрута.</p>
<p>Следующий шаг — самостоятельное описание запуска. Найди <a href="https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html">официальное руководство systemd.service</a>, затем выбери WorkingDirectory, User, ExecStart, ограничения перезапуска и журнал. Сверь установленную версию systemd с документацией. systemd уже входит в выбранную ОС: скачивать второй «systemd с сайта» поверх дистрибутива не требуется. Проверь unit анализатором, перечитай определения и запусти именно свой unit.</p>
<p>В паспорт службы внеси точные байты unit и фактическую команду процесса, каталог данных, порт, журнал и ожидаемый контрольный ответ. После штатного выключения и включения проверь выбранную политику автозапуска. Служба не считается настроенной, если она случайно жила только в забытом терминале. Для остановки используй управление конкретной службой; не очищай систему и не пересоздавай сеть.</p>
'''),
    'P07-storage-recovery': _block('Получить дисковые инструменты и добавить отдельный учебный носитель', r'''
<p>Сохрани основной диск с прежней ОС, сетью и приложением. Новым объектом будет дополнительный небольшой виртуальный диск либо файл-образ из задания. Его путь и серийный признак записываются до создания файловой системы. Отсутствие места на основном диске не является разрешением форматировать найденный по похожему имени раздел.</p>
<p>Открой документацию <a href="https://www.gnu.org/software/parted/manual/parted.html">GNU Parted</a> и <a href="https://www.kernel.org/doc/html/latest/filesystems/ext4/">ext4</a>, подготовь util-linux, e2fsprogs и parted своей Ubuntu; lvm2 добавляется только если выбран опыт с логическими томами. Зафиксируй версии, полный offline-набор и состояние пакетов. Не предполагается заранее установленный менеджер LVM.</p>
<p>Выключи гостя, сохрани cold-копию перед изменением виртуального железа и добавь новый файл диска в его описание без замены active_disk. Для текущего world.py дополнительный диск ещё не реализован готовым флагом: сначала требуется явная доработка и приёмка запуска либо ограниченный файл-образ внутри гостя. После включения сравни lsblk до/после и докажи выбранную принадлежность устройства.</p>
<p>Раздел, файловая система, том LVM и точка монтирования настраиваются как отдельные слои. Сначала проверь нужный файл/устройство, затем создай структуру только на новом объекте, выбери mountpoint, владельца и условия постоянного монтирования. Сохрани UUID, fstab и резерв его прежней версии. Проверь запись непривилегированной службой, штатное размонтирование и повторный запуск. Паспорт диска включает внешнее имя файла QEMU и внутренний UUID; это защищает от путаницы одинаковых /dev/vd* после изменения порядка. Данные HTTP/ОС из прежних стадий сохраняются.</p>
'''),
    'P08-git-config': _block('Первая установка Git и первая собственная история конфигурации', r'''
<p>Дома найди <a href="https://git-scm.com/downloads">официальные варианты установки Git</a>. Для нашего Linux-гостя выбери пакет Ubuntu и сохрани точную версию/зависимости для offline-установки; Windows-клиент нужен только если ты отдельно решил работать им на разрешённом компьютере. Не копируй рабочую пользовательскую конфигурацию вместе с личной историей.</p>
<p>После установки проверь git --version и git config --show-origin --list. Создай один личный репозиторий для изучаемых конфигов, затем задай identity именно локально этому репозиторию. Для публичного GitHub используй noreply, не рабочую почту. Проверь имя и email автора и коммитера до первой публикации. Секреты, диски VM, дампы и generated runtime не добавляй: ignore задаётся до первого git add, а уже отслеживаемый секрет игнорированием не удаляется из истории.</p>
<p>Сначала зафиксируй реальное текущее состояние SSH/сети/службы с их рабочими и ещё неисправными частями. Git хранит записанные файлы; он не захватывает живую таблицу маршрутов или весь диск автоматически. Скопируй нужные конфиги осмысленно и запиши, откуда применяются именно они. Для каждого следующего изменения сохраняются diff, проверка синтаксиса и наблюдение службы.</p>
<p>В паспорт Git войдут путь единственного основного репозитория, локальная identity, ветка, remotes, правила исключений и способ независимого резерва. Закрытие терминала не требует git init заново. При неизвестной ошибке сначала status/log/diff, затем исправление отдельным понятным commit; reset к исходному состоянию не является обязательным началом главы. Инициализация Git-репозитория не заменяет резерв данных PostgreSQL или выключенного qcow2.</p>
'''),
    'P09-go-service': _block('Самостоятельно поставить Go и собрать первый выпуск своего продукта', r'''
<p>Открой <a href="https://go.dev/dl/">официальный каталог Go</a> и <a href="https://go.dev/doc/install">инструкцию установки</a>. Выбирай Linux и архитектуру гостя, а не Windows хоста. Зафиксируй совместимость с go.mod проекта: язык требует не ниже 1.25; прежний проверенный комплект книги — 1.27.3, это паспорт эталона, а не указание без проверки брать любой latest. Для выбранного доступного выпуска сохрани архив, ожидаемый SHA-256 с официальной страницы и фактическую сумму.</p>
<p>Установи в отдельный версионный каталог, например /srv/study/tools/go-ВЕРСИЯ, и явно выбери его bin в PATH учебного пользователя. Не распаковывай новую версию поверх старого дерева. Проверь command -v go, go version, go env GOOS GOARCH GOPATH GOMOD GOTOOLCHAIN. Другой Go в интерактивном SSH и в service/агенте сборки — частая причина расхождения; путь записывается в паспорте.</p>
<p>Скопируй <a href="../go/labs/service/README.txt">исходный Go-проект</a> в один собственный репозиторий P08. Не переинициализируй его после каждого задания. Подготовленный пример имеет только стандартную библиотеку. Для будущих внешних модулей дома понадобится совместимый кэш/поставка зависимостей; go.sum сам не содержит исходный код. Настройка GOTOOLCHAIN=local исключает неожиданную загрузку иной toolchain, но потребует заранее правильного установленного комплекта.</p>
<p>Выполни тесты и сборку по README, исследуй dist/manifest.json, проверь SHA и встроенную версию. Установи артефакт в новый release-каталог и настрой уже изученную службу с явным -listen. Проверь /healthz и /greet локально и через прежний маршрут. Добавление новой программы не должно сбрасывать пользователя, правила сети или SSH. В паспорте Go/продукта сохраняются версия компилятора, исходный commit, флаги, кэш, бинарник, конфиг запуска, адрес, журнал и предыдущий работоспособный выпуск.</p>
'''),
    'P10-postgres-access': _block('Первая установка PostgreSQL и создание одного явного экземпляра', r'''
<p>Через <a href="https://www.postgresql.org/download/linux/ubuntu/">официальную страницу PostgreSQL для Ubuntu</a> выбери поддерживаемую основную версию и поставку. Системный пакет Ubuntu и официальный PGDG-репозиторий могут предоставлять разные версии. Для байтовых лабораторий книги нужен комплект ветки 18; старый фактический отчёт относится к 18.6. Запиши выбранный поддерживаемый minor, архитектуру, ключ подписанного репозитория и версии серверных/клиентских пакетов. Дома подготовь initdb, postgres, pg_ctl, psql, dump/restore/basebackup и зависимости; установи их в того же гостя offline.</p>
<p>Пакетная установка может создать и запустить дистрибутивный default cluster. Это отдельный экземпляр, а не автоматически наш изучаемый сервер. Посмотри pg_lsclusters, units и слушатели; запиши обнаруженный служебный экземпляр. Не подключайся к случайно найденному /var/run/postgresql и не стирай его ради освобождения знакомого порта. Для опыта явно выбираются /srv/study/pg-access/data, собственный socket-каталог и порт 55440.</p>
<p>Первичная инициализация initdb выполняется ровно один раз в новом private data-каталоге обычным пользователем. Если паспорт и PG_VERSION уже существуют, продолжай этот же кластер: проверь совпадение основной версии, конфиги, состояние и журналы, затем штатно запусти. Повторный initdb или второй access_lab не являются лечением неизвестной ошибки.</p>
<p>Следующий разбор миссии задаёт listen_addresses, socket, HBA, app_owner/app_rw/app_ro и object grants. Выполни его как полную настройку установки, включая неправильный пароль, запрещённый INSERT и отличие Unix-сокета от TCP. В паспорт PostgreSQL внеси точный bin_dir, PGDATA, config_file, hba_file, порт/сокет, владельца ОС, роли без паролей, журнал, backup-процедуру и контрольный SELECT. PostgreSQL приложения не подменяет внутреннюю БД будущего GitLab. Go-продукт пока к нему не подключён: это следующее явное изменение исходников.</p>
'''),
    'P11-database-recovery': _block('Продолжить PostgreSQL: проверить копию именно своего состояния', r'''
<p>Новой установки сервера и новой пустой исходной базы здесь нет. Возьми паспорт PostgreSQL P10, те же бинарники, private PGDATA и socket. Добавь недостающие утилиты из той же выбранной поставки: pg_dump, pg_dumpall, pg_restore, pg_basebackup и pg_verifybackup. Их наличие и версии проверяются до копирования; старый случайный pg_dump из PATH может не читать новый сервер.</p>
<p>Проверь, что архив сделан с действительного access_lab, а не с одноимённой базы другого экземпляра. Сохрани данные, роли, зависимости, размер, сумму и версии в новый набор /srv/study/backups, не поверх единственной прошлой копии. Настрой расписание и журнал исходов после первого проверенного ручного восстановления. Файл «создан» не является статусом «восстановление принято».</p>
<p>Для проверки создаётся отдельная recovery_check либо отдельный восстановленный экземпляр с отличимым socket/портом. Это необходимая цель восстановления, а не сброс основного мира. Исходная access_lab сохраняется. HBA и CONNECT новой базы тоже должны быть настроены; новый успешный вход и отрицательные права проверяются отдельно от административной загрузки архива.</p>
<p>Приложенный postgres-lab.py создаёт независимые /tmp-кластеры для своих опытов. Он полезен как читаемый воспроизводимый пример PITR, но не заменяет ваш постоянный экземпляр и не является кнопкой подготовки следующей главы. В паспорте резерва зафиксируй пригодную точку истории, полноту WAL для физического маршрута, место копий и измеренный срок восстановления. Перед P12 продолжает работать исходный PostgreSQL с прежними ролями и данными, а не случайно оставленный recovery_check.</p>
'''),
    'P12-cache-effectiveness': _block('Первая установка кэша: один постоянный Redis', r'''
<p>Выбери Redis как первый изучаемый продукт и найди <a href="https://redis.io/docs/latest/operate/oss_and_stack/install/install-redis/install-redis-on-linux/">официальную установку Linux</a>. Сверь поддержку выбранной Ubuntu, редакцию и лицензионные условия выпуска, затем подготовь пакет/архив и все зависимости. Старые отчёты книги на 7.0.15 — фактический эталон семантики, не рекомендация ставить устаревший upstream без учёта поддержки. Зафиксируй точный поддерживаемый пакет и проверь redis-server --version и redis-cli --version после offline-установки в госте.</p>
<p>До первого старта создай отдельные /srv/study/redis/config, data и logs с владельцем процесса и закрытым доступом. Явно выбери bind 127.0.0.1 и свободный учебный порт, например 16379, файл конфигурации, режим daemonize/unit и pid/log. Не принимай работавший на этом порту чужой процесс за свой. Выбери политику maxmemory/maxmemory-policy по цели опыта и зафиксируй решение о persistence: даже восстановимый кэш может намеренно терять содержимое при рестарте, но это должно быть явным изучаемым свойством.</p>
<p>Настрой ACL: отдельная личность приложения с нужными командами и префиксом ключей, отдельный административный вход. Секрет запрашивается и хранится в личном закрытом файле предусмотренным выбранной версией способом, не вставляется в argv/публичную конфигурацию. Сначала проверь новый вход и запрет чужого префикса, потом ограничивай прежний доступ. Для более позднего сетевого адреса потребуется отдельное решение о TLS/маршруте; loopback-пример не публикуется наружу.</p>
<p>Проверь PING/SET/GET/PTTL, неверную аутентификацию, выбранную политику памяти и штатный restart того же экземпляра. Сохрани redis.conf/ACL, адрес, версию, журнал и выбранное восстановление в паспорт. Основные ключи опыта живут здесь; новый раздел не очищает их FLUSHALL. Одноразовый live.py --manual создаёт временные Redis/Memcached и удаляет их при завершении, поэтому остаётся только дополнительным отдельным опытом. Memcached при выборе сравнительной ветки впервые устанавливается самостоятельно по <a href="https://docs.memcached.org/serverguide/">официальному руководству</a> с собственным портом и паспортом; он не считается частью уже установленного Redis.</p>
'''),
    'P13-observability': _block('Первый сборщик метрик: подготовить, установить и настроить', r'''
<p>Исходный сервис, PostgreSQL и Redis продолжаются с прежними адресами и данными. Начальный observe.py — собственный скрипт книги, которому нужен уже проверенный Python; новый сервер мониторинга он не устанавливает. Прежде добавления платформы проверь этот локальный измерительный путь.</p>
<p>Дома самостоятельно открой <a href="https://prometheus.io/download/">каталог Prometheus</a>, выбери поддерживаемые Prometheus и node_exporter для Linux/архитектуры гостя. Сохрани архивы и официальные SHA-256, проверь их и распакуй каждый в свой версионный каталог /srv/study/tools. Изучи <a href="https://prometheus.io/docs/prometheus/latest/getting_started/">официальный первый запуск</a>. На работе установка выполняется из этого комплекта, без Docker и внезапной загрузки зависимостей.</p>
<p>Создай /srv/study/prometheus с config, data и logs. В конфигурации задай интервалы, конечные адреса сбора, отличимые job/instance и ограничение хранения для маленького диска. Сначала добавь самого Prometheus и локальный node_exporter; проверь promtool check config, затем слушатели только на выбранных учебных адресах. Успешный target должен иметь новые отметки времени; остановленный exporter — обнаруживаемую недоступность, а не нулевую «здоровую» нагрузку. Применяй параметры запуска из help установленного релиза и запиши фактический data-path.</p>
<p>Если выбрана Grafana, впервые найди её <a href="https://grafana.com/docs/grafana/latest/setup-grafana/installation/debian/">официальную Ubuntu-поставку</a>, подготовь подписанный пакет и зависимости. Установи отдельного пользователя/каталоги, ограничь слушатель, выполни первый административный вход и настрой datasource на проверенный Prometheus. Сохрани provisioning/dashboard и резерв БД/конфигурации Grafana; импорт красивой панели без работающего datasource не завершает установку. Grafana необязательна для первых проверок Prometheus.</p>
<p>Паспорта связывают версии, SHA, конфиги, хранилища, порты, доступ и журналы. Следующие измерения идут в те же данные; очистка временных рядов не является началом нового задания. Встроенный HTTP-измеритель проверен отдельно, постоянный профиль этих платформ ещё предстоит принять в вашей VM.</p>
'''),
    'P14-manual-release': _block('Первый входной прокси: установить и настроить NGINX', r'''
<p>Продолжай существующий Go-репозиторий и его сохранённые выпуски. Новая технология здесь — входной прокси. На <a href="https://nginx.org/en/linux_packages.html">официальной странице NGINX</a> сравни пакет Ubuntu и репозиторий проекта, выбери одну поддерживаемую поставку и точную версию. Сохрани проверенные пакеты/зависимости до поездки; не смешивай бинарник одного источника с модулями другого.</p>
<p>Перед установкой запиши уже занятые порты. Пакет может автоматически запустить штатный unit: выясни его состояние и не путай его с выбранным собственным экземпляром. Для учебного профиля определи единственный способ запуска, конфиг /srv/study/nginx/nginx.conf, pid/log, доступный пользователю рабочий каталог и входной адрес. Фиксированный путь не возникает от строки в книге — его создаёт владелец гостя.</p>
<p>В одном сетевом пространстве Go blue и green слушают 127.0.0.1:8087 и :8088; upstream прокси сначала указывает на blue. Если роли в разных namespace/VM, loopback заменяется их действительными доступными адресами. Настрой server/listen, location и proxy_pass, нужные заголовки и timeout. Проверь nginx -t с фактическим conf-path, запусти и проверь клиентский URL. Затем настрой TLS из P05, если он входит в ваш выбранный вход; никакой новый CA автоматически не ставится на рабочий Windows.</p>
<p>До переключения сохрани действующий конфиг и критерий функционального ответа. После reload проверь новые клиентские запросы и старые соединения; затем штатно перезапусти тот же экземпляр и докажи сохранение маршрута. В паспорт прокси входят источник/версия, модули, файл конфигурации, namespace, вход/выход, журнал, сертификат и процедура возврата. Приложение и данные не пересобираются заново при смене upstream.</p>
'''),
    'P15-jenkins-delivery': _block('Первая установка Jenkins: Java, WAR, плагины и агент', r'''
<p>Сначала найди <a href="https://www.jenkins.io/download/">официальную LTS-поставку Jenkins</a> и <a href="https://www.jenkins.io/doc/book/platform-information/support-policy-java/">матрицу Java</a>. Выбери совместимую пару, сохрани WAR и ожидаемую сумму из доверенного источника. Набор книги проверял 2.580.2 с Java 21; другой выпуск требует новой проверки совместимости, а не переименования старого файла. Java готовится из поддерживаемого пакета Ubuntu со всеми зависимостями.</p>
<p>По <a href="https://www.jenkins.io/doc/book/installing/war-file/">официальной инструкции WAR</a> установи отдельный JENKINS_HOME, пользователя, слушатель 127.0.0.1 и свободный порт, например 18080. До старта проверь java -version и SHA WAR. Тот же порт в уже работающем NGINX/GitLab не освобождается остановкой случайного процесса: карта портов уточняется явно.</p>
<p>Первый запуск включает unlock, собственного администратора, политику доступа и выбранные плагины. Для offline-работы дома подготовь полный совместимый набор плагинов и зависимостей, а не только названия из Jenkinsfile. Сверь <a href="../jenkins/labs/plugins.lock.txt">эталонный lock</a> с выбранным WAR и сохрани фактические версии/хеши. После установки перезапусти, проверь загрузку плагинов и повторный вход.</p>
<p>Отключи исполнители встроенного узла, подготовь отдельного агента с нужной Java и уже установленными Git/Go/Python. Настрой trust/credentials и метку handbook-local, проверь пути инструментов от агентского пользователя. Создай Pipeline над существующим чистым продуктовым репозиторием, выполни отрицательный тест без доставки и только потом подключай процедуру P14.</p>
<p>Паспорт Jenkins содержит WAR/Java/plugins, home, агент, рабочую область, адрес и журнал, способ защищённого резерва home с ключами и контрольный build. После паузы запускается тот же home с историей и ошибками. Повторный мастер установки вместо поиска прежнего каталога не является продолжением курса.</p>
'''),
    'P16-ansible': _block('Первая установка Ansible: свой управляющий каталог и один узел', r'''
<p>Дома открой <a href="https://docs.ansible.com/projects/ansible/latest/installation_guide/intro_installation.html">официальную установку Ansible</a>, сверь поддерживаемые версии Python управляющего и целевого узла. Для первых built-in-модулей выбери ansible-core; полный пакет ansible с коллекциями — другая поставка. Запиши конкретную версию и зависимости.</p>
<p>Создай отдельное Python-окружение в госте, например /srv/study/tools/ansible. Если python3-venv отсутствует, подготовь его пакеты перед этой стадией. Дома собери wheelhouse выбранного ansible-core и зависимостей для той же ОС/Python/архитектуры; проверь хеши и автономную установку pip с --no-index и --find-links. Установка в venv не меняет системные Python-пакеты. Коллекции, если понадобятся, заранее сохраняются отдельными версиями и зависимостями.</p>
<p>В /srv/study/automation/ansible создай свой ansible.cfg, inventory и первый playbook над существующим учебным сервером. Проверь ansible --version: он показывает используемый конфиг и пути. Сверь состав inventory до подключения; используй доверенный SSH из P01/P02, явно выбранного пользователя и ограниченное become. Управляющий узел не обязан быть рабочим Windows: он живёт внутри переносимой VM.</p>
<p>Применение сначала касается одного нового конфигурационного файла, без перезаписи PostgreSQL/Redis или повторного initdb. Проверь первый эффект, повтор без изменения, управляемый параметр и исправление ручного дрейфа. В паспорт входят версия/venv/коллекции, inventory/config, SSH-путь, журнал запуска и резерв исходных управляемых файлов. Следующие playbook продолжают эти роли и реальные данные; клонирование чистой машины — отдельный сравнительный опыт, не автоматический сброс основного мира.</p>
'''),
    'P17-terraform': _block('Первая установка Terraform и первый локальный state', r'''
<p>Найди <a href="https://developer.hashicorp.com/terraform/install">официальную поставку Terraform</a>, выбери поддерживаемую версию Linux/архитектуры гостя, сохрани архив, SHA256SUMS и подпись. Проверь происхождение ключа и подпись списка, затем сумму бинарника. Встроенный terraform_data примера требует соответствующей версии Terraform; старый случайный бинарник не получает новые возможности от копирования HCL.</p>
<p>Установи в отдельный версионный tools-каталог, проверь terraform version и выбери /srv/study/automation/terraform для одного продолжающегося описания. Настрой исключение state, backup-state, .terraform и сохранённых планов из публичного Git до первого init. Код и lock-файл хранятся иначе, чем чувствительное действительное состояние.</p>
<p>Первое упражнение использует встроенный terraform_data без платного облака и внешнего провайдера. Создай конфиг из разбора, выполни init, validate, plan, проверь план, затем apply. Проверь state list/show, повторный план и одно изменение входного значения. Здесь не создались VM и сетевой адрес: этот факт является контрольной границей установки, а не скрытой неудачей.</p>
<p>Для реального ресурса сначала выбери провайдер и права на одну свою цель. Дома подготовь его точную версию и зависимости через <a href="https://developer.hashicorp.com/terraform/cli/commands/providers/mirror">официальный providers mirror</a> для нужной платформы; настрой filesystem_mirror и проверь init без интернета. Lock-файл не содержит исполняемый плагин. Пока такой провайдер личного мира не выбран, apply не объявляется готовым способом создавать машины.</p>
<p>В паспорт Terraform входят бинарник/подпись, каталоги конфигов и зеркала, версия провайдера, backend/state/lock, идентичность учётной записи без ключа, журнал плана и согласованное восстановление state. Следующее упражнение открывает этот же рабочий каталог; удаление state или terraform destroy не является штатной подготовкой следующей главы.</p>
'''),
    'P18-replica-failure': _block('Из прежнего PostgreSQL — к реплике, затем к управлению группой', r'''
<p>Первый PostgreSQL P10 остаётся тем же ведущим учебным экземпляром с накопленными данными. Перед добавлением реплики проверь паспорт, версию и пригодное восстановление P11. Второй пустой PGDATA создаётся как отдельная роль и получает согласованную базовую копию; это не второй initdb поверх исходного сервера. Подготовь бинарники совместимой основной версии и отдельные каталоги/порты/socket.</p>
<p>По <a href="https://www.postgresql.org/docs/18/warm-standby.html">официальной потоковой репликации</a> настрой узкую роль REPLICATION и HBA, маршрут, wal_level, нужное число sender и политику удержания WAL. Настрой standby.signal/primary_conninfo предусмотренным способом, не печатай пароль в журнале. Проверь состояние ведущего и реплики, доставку новой контрольной записи, отказ записи на ведомом и поведение разрыва. Ручное promote создаёт новую историю; возвращать прежний ведущий без анализа нельзя.</p>
<p>Patroni и etcd впервые добавляются только после этого понятного ручного маршрута. Найди <a href="https://patroni.readthedocs.io/en/latest/installation.html">официальные зависимости Patroni</a> и <a href="https://etcd.io/docs/v3.6/install/">поставку etcd</a>. Подготовь проверенные версии, Python-wheelhouse с выбранным драйвером PostgreSQL и клиентом etcd, отдельный бинарник etcd/etcdctl. Один пакет patroni без драйвера и DCS не является установленной группой.</p>
<p>Самостоятельно выбери состав и ресурсный профиль, configure scope/name, data_dir/bin_dir, адреса PostgreSQL/REST, закрытую аутентификацию и DCS endpoints. У каждого etcd — собственные name/data-dir, peer/client URLs, сертификаты и резерв; один member не даёт отказоустойчивый quorum. Не запускай Patroni как второго независимого владельца процесса рядом с прежним pg_ctl/systemd. Перевод существующего PostgreSQL под его управление требует отдельной сохранённой точки и проверенной процедуры принятия данных.</p>
<p>Паспорт группы фиксирует все роли, историю/LSN, параметры синхронности, способ блокирования прежнего ведущего, маршрутизацию клиента, данные/конфиги/секретные пути и восстановление DCS. Три роли в одной VM не переживут потерю этой VM. Интегрированный профиль ещё не поднят: его нельзя объявить принятым по одному patronictl list. Предыдущий мир не откатывается автоматически после сетевого отказа.</p>
'''),
    'P19-kubernetes': _block('Первая установка Kubernetes через kind: заранее собрать автономный комплект', r'''
<p>Продолжается прежний продукт и его артефакт. Docker Engine должен быть уже осмысленно установлен внутри Linux-гостя: соответствующая первая установка разобрана в <a href="#P20-gitlab-platform">стадии платформы GitLab</a>, которая в маршруте книги идёт раньше. Если этот этап пропущен, сначала выполни только её подготовку Docker, а не пытайся запустить kind неизвестным daemon. Docker Desktop на рабочий Windows не устанавливается как побочный эффект этого задания.</p>
<p>Дома найди <a href="https://kind.sigs.k8s.io/docs/user/quick-start/">официальный релиз kind</a> и <a href="https://kubernetes.io/docs/tasks/tools/install-kubectl-linux/">kubectl для Linux</a>. Выбери совместимую пару и поддержанный образом kind выпуск Kubernetes, проверь опубликованные суммы. По <a href="https://kind.sigs.k8s.io/docs/user/working-offline/">offline-руководству kind</a> сохрани точный node image с digest, слои приложения и диагностического образа. Строки имён в YAML не содержат эти байты.</p>
<p>Установи бинарники в выбранный tools-каталог, проверь версии и Docker. Загрузку архивов образов выполняй в Docker того же гостя. Создай собственный kind-config с одним исходным узлом, явным loopback API endpoint и ресурсным бюджетом. До команды create проверь kind get clusters: если study уже существует, продолжается он, новый create не нужен. Загрузи выбранные образы на узлы kind предусмотренной командой.</p>
<p>Настрой отдельный kubeconfig/контекст kind-study и namespace study; проверь ready узлы, системный DNS и один новый Pod. Затем добавляй Deployment/Service продукта из разбора, readiness и отрицательный неверный образ. Рабочий kubeconfig другого кластера не участвует. В паспорт входят kind/kubectl/node digest, config, kubeconfig с секретным доступом, загрузка образов, namespaces, данные и резерв.</p>
<p>На следующий день запускаются те же контейнеры узлов и сохраняемые данные; kind delete cluster не является выходом из главы. Перед первой поездкой проверь холодный старт без интернета. Управляющее состояние внутри узлов, PVC и внешний резерв — разные слои; потеря общего гостя остаётся общим отказом.</p>
'''),
    'P20-gitlab-platform': _block('Первая установка Docker и GitLab: настроить постоянную платформу', r'''
<p>В этом маршруте Docker впервые нужен для собственной контейнерной платформы. Дома найди <a href="https://docs.docker.com/engine/install/ubuntu/">официальную Ubuntu-установку Docker Engine</a>. Выбери поддерживаемую ОС/архитектуру, способ поставки и точные версии Engine/CLI/containerd/Compose plugin. Подготовь подписанные пакеты со всеми зависимостями; удобный сетевой install-скрипт не является автономным комплектом. Устанавливай внутри своей Linux VM, не на рабочем Windows.</p>
<p>После offline-установки выясни daemon config, data-root, unit, журнал и права доступа. Проверь docker version, docker info и docker compose version; клиент без daemon не означает готовый Docker. Членство в группе docker даёт сильные полномочия над машиной и не выдаётся случайным пользователям. До публикации портов изучи взаимодействие Docker с фильтрами; не очищай nft ruleset существующего учебного маршрутизатора. Сначала проверь собственный заранее подготовленный образ с ограниченным запуском и сохранёнными данными.</p>
<p>Теперь на <a href="https://docs.gitlab.com/install/docker/installation/">официальной установке GitLab</a> выбери редакцию и поддерживаемый точный выпуск. Запиши tag и digest, сохрани образ через docker save и проверь offline docker load в госте. Заранее подготовь полный комплект <a href="https://docs.gitlab.com/runner/install/linux-repository/">GitLab Runner</a>, helper и образов jobs; Runner не содержится автоматически в server image. Выбери executor и одну исходную конкурентную работу по ресурсу.</p>
<p>Создай постоянные config/data/logs, внешний URL, DNS и TLS по <a href="../gitlab/index.html#02-install-and-addresses">разбору установки тома GitLab</a>. В шаблоне внутренние порты привязаны к loopback; доступ из другой VM требует именно подготовленного входного прокси, а не случайной замены на 0.0.0.0. Сверь карту портов: Jenkins мог занять 18080; выбери отличимый порт GitLab и измени все связанные настройки. Встроенную БД GitLab не направляй в access_lab приложения.</p>
<p>Пройди bootstrap администратора, создай обычного пользователя/проект, настрой Runner с узким authentication token и фактическими CA/маршрутом его среды. Проверь push, загрузку artifact, отказ без прав, stop/start с сохранением проекта и первый backup. В паспорт попадают image/digest/пакеты, Compose, постоянные каталоги, URL/CA, runner config без токена, журналы, резерв и проверка восстановления. Не используй down -v как ежедневное завершение. Серверный/runner-профиль ещё не развёрнут в этом наборе, а прежние Jenkins/Go/Git продолжают своё состояние.</p>
'''),
    'P21-capacity-budget': _block('Продолжить установленные системы: принять измерительный комплект', r'''
<p>Здесь не устанавливается новый кластер ради красивой нагрузки. Подними только нужные прежние экземпляры по их паспортам и проверь накопленные конфиги/данные. Отдельно зафиксируй все изменения с последнего измерения: версия Go, схема PostgreSQL, размер и прогрев Redis, число процессов, ускоритель VM и фоновые службы.</p>
<p>Используй измеритель P13 и уже установленный инструментарий. Если выбран другой генератор, до поездки самостоятельно найди его официальный источник, версию/сумму, зависимости и описание модели нагрузки; сначала прими его на маленьком известном тесте. Скачанный бинарник без проверки расписания, таймаутов, тел ответов и учёта ошибок не становится метрологическим эталоном. Не добавляй несколько генераторов одновременно только ради списка названий.</p>
<p>Создай постоянный каталог серий /srv/study/measurements с входным набором, сохранённым seed/порядком ключей, версиями, временными границами и исходными результатами. Новая серия получает новое имя, прежняя не затирается. Для тёплого и холодного режимов заранее выбери отдельный смысл: очистить кэш — осознанное изменение конкретного опыта, а не скрытый сброс системы.</p>
<p>Приёмка инструмента включает правильный ответ, быстрый HTTP-отказ, таймаут, малое число успешных ответов и перегруженный сам генератор. Сопоставь число попыток с серверным журналом. Паспорт серии ссылается на паспорта реальных экземпляров и настройки нагрузки. После снятия нагрузки исправляются найденные проблемы в существующем мире; результаты не улучшаются переинициализацией базы или удалением неудачных запросов из отчёта.</p>
'''),
    'P22-network-tool-migration': _block('Первое знакомство с новым сетевым инструментом — только по выбранной ветке', r'''
<p>Packet Tracer, .pkt и Linux-стек остаются прежними. Сначала повтори один пакетный контракт и сохрани различия; переустановка PT и netlab down/up не нужны. Следующий инструмент выбирается по недостающему свойству, не все четыре устанавливаются заранее. Они пока не входят в готовый переносимый комплект.</p>
<p><strong>GNS3 либо EVE-NG.</strong> Самостоятельно открой <a href="https://docs.gns3.com/docs">официальную установку GNS3</a> или <a href="https://www.eve-ng.net/index.php/documentation/">EVE-NG</a>, выбери поддержанную платформу/версию и бюджет. Сохрани installer/appliance с проверяемым происхождением и отдельно разрешённые для этой платформы образы ОС. Шаблон устройства не содержит сам образ. После установки настрой управляющий адрес, каталоги проектов/дисков, консоль, сетевые связи и захват; прими одну простую топологию, cold-stop/start и сохранение конфига. Hypervisor/nested virtualization и доступ на Windows проверяются до обещания работы.</p>
<p><strong>Cisco CML.</strong> По <a href="https://developer.cisco.com/docs/modeling-labs/">официальной документации</a> сначала проверь доступную редакцию, условия использования, образ установки, требования и разрешённые Cisco images. Поставка для CML не считается автоматически разрешённой для любого иного эмулятора. Настрой управляющую сеть и доступ, получи консоль одного узла, сохрани проект/конфигурацию, проверь перезапуск. Приобретение и развёртывание здесь не выполнены.</p>
<p><strong>containerlab.</strong> По <a href="https://containerlab.dev/quickstart/">официальному старту</a> сначала проверь Docker. В основном маршруте он вводится в P20; эту необязательную ветку можно отложить до него либо выполнить сейчас только ввод Docker по P20, сохранив паспорт для последующего продолжения. Затем выбери бинарник containerlab для своего Linux, закрепи версию, получи разрешённые node images и их слои до offline-периода. Опиши минимальные nodes/links, управляющую сеть и сохранение startup config в личном каталоге. Сначала исследуй inspect/deploy и сохранение данных; destroy не является способом обычной остановки или первым знакомством с тем, где лежала единственная копия конфига.</p>
<p>Для выбранной ветки создаётся свой паспорт: версия/сумма, права на образы, гипервизор, пути проектов и изменяемых дисков, интерфейсы управления, учётные данные отдельно, журналы и резерв. Контрольный критерий — объяснённый путь пакета, сохранённое изменение и повторная работа после закрытия, а не только зелёная иконка нового приложения. Производительность физического ASIC/кабеля/радио из этой приёмки не следует.</p>
'''),
}


